import {newMentor,mentorSeed,mentorCoverage,mentorStep,restoreMentor} from './mentor.js';
import {lessonLens,mentorEvidence,mentorEvidenceCSV} from './mentor-analysis.js';
const mentorRoot=document.querySelector('#app'),mentorTokens=['sun','leaf','star','moon'],mentorIcons={sun:'☀',leaf:'❧',star:'★',moon:'☾'},mentorNames={unsure:'not sure yet',left:'the left piece',right:'the right piece',equal:'same-sized pieces',sun:'sun',leaf:'leaf',star:'star',moon:'moon'};
const mEsc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const mRead=k=>{try{return JSON.parse(window.fixiverseStorage.getItem(k)||'null');}catch{return null;}};
const mKey=m=>`fixiverse-mentor-${m}-v1`;
let mentorState=null,mentorError='',mentorLensIndex=0,mentorLensOpen=false;
const mButton=(text,action,attrs='',quiet=false)=>`<button class="${quiet?'quiet':'btn'}" data-mentor="${action}" ${attrs}>${text}</button>`;
const mTaskName=t=>t.kind==='fraction'?`1/${t.pair[0]} and 1/${t.pair[1]}`:`${t.block.join(' / ')} · ${t.length} shown`;
function mentorVisual(t){if(t.kind==='fraction')return`<div class="lab-fraction-model">${t.pair.map((n,i)=>`<div class="growth-bar-line"><span class="fraction" aria-label="one over ${n}"><em>1</em><i>${n}</i></span><div><span class="growth-bar-label">${i?'RIGHT':'LEFT'} WHOLE · ONE SHADED PIECE</span><div class="fraction-bar" role="img" aria-label="${i?'Right':'Left'} matching whole in ${n} equal parts, one shaded">${Array.from({length:n},(_,j)=>`<i class="part ${j?'':'selected'}"></i>`).join('')}</div></div></div>`).join('')}<p class="hint-text">Same-sized wholes. Equal parts. Compare one piece from each.</p></div>`;const tile=(v)=>`<span class="grove-tile ${v}" role="img" aria-label="${v}">${mentorIcons[v]}</span>`;return`<p class="eyebrow">THE LITTLE LOOP</p><div class="lab-small-loop">${t.block.map(tile).join('')}</div><p>Follow this whole loop. Start again after the last tile.</p><div class="pattern-path">${Array.from({length:t.length},(_,i)=>tile(t.block[i%t.block.length])).join('')}<span class="grove-tile mystery" role="img" aria-label="Missing next tile">?</span></div>`;}
function mentorControls(){const t=mentorState.task;return`<div class="lab-case-controls">${t.kind==='fraction'?t.pair.map((n,i)=>`<label>${i?'Right':'Left'} whole<select data-mentor-field="part-${i}" aria-label="${i?'Right':'Left'} teaching parts">${Array.from({length:7},(_,j)=>`<option value="${j+2}" ${n===j+2?'selected':''}>${j+2} equal parts</option>`).join('')}</select></label>`).join(''):`<label>Loop size<select data-mentor-field="size" aria-label="Teaching loop size"><option value="2" ${t.block.length===2?'selected':''}>2 different tiles</option><option value="3" ${t.block.length===3?'selected':''}>3 different tiles</option></select></label>${t.block.map((v,i)=>`<label>Tile ${i+1}<select data-mentor-field="token-${i}" aria-label="Teaching tile ${i+1}">${mentorTokens.map(x=>`<option value="${x}" ${x===v?'selected':''}>${x}</option>`).join('')}</select></label>`).join('')}<label>Path length<select data-mentor-field="length" aria-label="Teaching path length">${Array.from({length:7},(_,i)=>`<option value="${i+2}" ${t.length===i+2?'selected':''}>${i+2} tiles</option>`).join('')}</select></label>`}</div>`;}
function mentorChoices(){const s=mentorState,locked=s.phase==='challenge'&&s.challenges[s.challengeIndex].checked;return`<div class="lab-answer-choices" role="group" aria-label="Your teaching prediction">${(s.mission==='fraction'?['left','equal','right']:mentorTokens).map(v=>`<button class="choice ${s.choice===v?'selected':''}" data-mentor="choose" data-value="${v}" aria-label="${s.mission==='fraction'?{left:'Left piece',equal:'Same size',right:'Right piece'}[v]:v}" aria-pressed="${s.choice===v}" ${locked?'disabled':''}>${s.mission==='fraction'?{left:'Left piece',equal:'Same size',right:'Right piece'}[v]:`${mentorIcons[v]} ${v}`}</button>`).join('')}</div>${mButton('I’m not sure yet','choose',`data-value="unsure" aria-pressed="${s.choice==='unsure'}" ${locked?'disabled':''}`,true)}`;}
function mentorNotebook(){const s=mentorState,c=mentorCoverage(s);return`<aside class="lab-notebook mentor-notebook"><div class="eyebrow">PIP’S LEARNING NOTEBOOK</div><div class="mentor-pip" aria-hidden="true"><div class="robot"><div class="robot-screen"><i class="eye"></i><i class="eye"></i></div><div class="robot-mouth"></div></div></div><h2>You get to be <br>the teacher.</h2><p>Pip follows <b>one of four possible rules</b>. Each example you teach rules out ideas that do not fit.</p><details><summary>What rule is Pip using?</summary><p>${mEsc(c.rule)}</p><p>This is an example-learning simulation. Pip does not read or grade your words.</p></details><h3>Your teaching examples</h3>${s.examples.length?`<ol>${s.examples.map(e=>`<li><b>${mEsc(mTaskName(e.task))}</b><span>You taught: ${mentorNames[e.choice]}.</span></li>`).join('')}</ol>`:'<p>Your first example will go here.</p>'}${s.phase==='teach'&&s.examples.length?mButton('Take back my last example','undo','',true):''}<p class="lab-small">You can change your mind. Pip’s mistakes are a clue about its rule, not a score for you.</p></aside>`;}
function teachingPanel(){const s=mentorState;return`<section class="panel mentor-teach"><div class="panel-head"><span class="panel-title">01 / Build your lesson</span><span class="label">YOUR EXAMPLES CHANGE PIP</span></div><div class="panel-body"><h2>What will you teach Pip?</h2><p>Use the controls to build an example. Choose the answer you want to teach. You can test Pip on new examples after your first lesson.</p>${s.linked?'<p class="mentor-seed-note">A familiar puzzle, a new role. Pip started with a rule matching an earlier response in this learner’s work.</p>':''}${mentorControls()}${mentorVisual(s.task)}<h3>${s.mission==='fraction'?'Which shaded piece is bigger?':'Which tile comes next?'}</h3>${mentorChoices()}<div class="btn-row">${mButton('Teach Pip this example','teach',s.choice?'':'disabled')}${mButton('Show me how to compare','hint','',true)}</div>${s.feedback?`<p class="result soft" role="status">${mEsc(s.feedback)}</p>`:''}${s.examples.length?`<div class="mentor-next"><p><b>${s.examples.length} ${s.examples.length===1?'example':'examples'} in your lesson.</b> Has Pip learned the idea, or just a rule that fits these examples?</p>${mButton('Test Pip on 3 new examples →','challenge')}</div>`:''}</div></section>`;}
function challengePanel(){const s=mentorState,c=s.challenges[s.challengeIndex];return`<section class="panel"><div class="panel-head"><span class="panel-title">02 / Try a new example</span><span class="label">${s.challengeIndex+1} OF 3</span></div><div class="panel-body"><h2>Can Pip use what you taught?</h2><p>This is a new example. Choose your answer first. Then reveal Pip’s answer to compare both ideas.</p>${mentorVisual(c.task)}<h3>Your idea first</h3>${mentorChoices()}<div class="btn-row">${mButton('Show me how to compare','hint','',true)}</div>${s.feedback?`<p class="result soft" role="status">${mEsc(s.feedback)}</p>`:''}${c.checked?`<div class="mentor-comparison"><article><span>YOUR IDEA</span><b>${mEsc(mentorNames[c.choice])}</b><p>${c.teacherCorrect?'Your prediction fits the model.':'Let’s trace the model together.'}</p></article><article><span>PIP’S SEALED IDEA</span><b>${mEsc(mentorNames[c.pip])}</b><p>${c.pipCorrect?'Pip used its rule successfully here.':'Pip’s rule still needs another kind of example.'}</p></article></div><p class="result soft" role="status">The model shows ${mEsc(mentorNames[c.expected])}. ${c.pipCorrect?'Your teaching examples helped Pip reach this answer.':'You found a gap in Pip’s lesson. A different example can help.'}</p>${mButton(s.challengeIndex===2?'See what my lesson changed →':'Next new challenge →','next')}`:mButton('Open Pip’s answer and check','check',s.choice?'':'disabled')}</div></section>`;}

function mentorLensPanel(){const s=mentorState;if(!s.examples.length)return '';const lens=lessonLens(s),index=Math.min(mentorLensIndex,s.examples.length-1),item=lens.examples[index];return `<details class="mentor-lens" id="mentor-lens" ${mentorLensOpen?'open':''}><summary>What did my examples change?</summary><div class="mentor-lens-body"><h3>A little lesson detective work.</h3><p>Try leaving one example out. Which ideas could Pip still be using?</p><p class="mentor-core"><b>${lens.minimum.length} of your ${s.examples.length} examples</b> are enough for the same rule evidence in this four-rule collection: ${lens.minimum.map(i=>`example ${i+1}`).join(', ')||'no examples yet'}.</p><p class="lab-small">This is the smallest subset of your recorded examples with the same ruled-out ideas. It does not say how many examples a person needs to learn.</p><div class="mentor-lens-options" role="group" aria-label="Example to leave out">${lens.examples.map(e=>mButton(`Leave out example ${e.index+1}`,'inspect',`data-index="${e.index}" aria-pressed="${e.index===index}"`,true)).join('')}</div><h3>What if we left out example ${index+1}?</h3><p>You taught: ${mEsc(mTaskName(item.task))}.</p>${item.uniqueEvidence?`<p>Without it, ${item.restoredRules.map(h=>mEsc(h.name)).join('; ')} ${item.restoredRules.length===1?'still fits':'still fit'} your other examples.</p>${item.witness?`${mentorVisual(item.witness.task)}<div class="mentor-comparison"><article><span>WITHOUT THIS EXAMPLE · POSSIBLE ANSWERS</span><b>${item.witness.withoutChoices.map(v=>mEsc(mentorNames[v])).join(' / ')}</b></article><article><span>WITH YOUR FULL LESSON · POSSIBLE ANSWERS</span><b>${item.witness.withChoices.map(v=>mEsc(mentorNames[v])).join(' / ')}</b></article></div><p>This is a case where your example removes an extra possible answer. The model shows ${mEsc(mentorNames[item.witness.expected])}.</p>`:''}`:'<p>Your other examples already supply the same rule evidence. This one can still be useful practice; it adds no unique rule evidence in this lesson.</p>'}<p class="lab-small">This is a preview. Your real lesson and Pip’s saved rule stay as they are. Possible answers include every rule that still fits, not just Pip’s first choice.</p></div></details>`;}
function mentorLearnerEvidence(s){const e=mentorEvidence(s);return `<div class="mentor-learner-evidence"><h4>The learner’s own responses</h4><p>Latest round: ${e.counts.fits} fit the model · ${e.counts.revisit} to revisit · ${e.counts.unsure} unsure. ${e.latest.length}/3 responses recorded.</p><details><summary>See responses and support</summary><div class="evidence-table-wrap"><table class="evidence-table"><caption>Latest round. Model traces are counted for each item; adult help is a lesson-level self-report.</caption><thead><tr><th>Task</th><th>Learner / model</th><th>Response / traces</th></tr></thead><tbody>${e.latest.map(row=>`<tr><td>${mEsc(mTaskName(row.task))}</td><td>${mEsc(mentorNames[row.choice])} / ${mEsc(mentorNames[row.expected])}</td><td>${{fits:'Fits the model',revisit:'Revisit',unsure:'Unsure'}[row.outcome]} · ${row.itemTraces??'unknown'} traces</td></tr>`).join('')||'<tr><td colspan="3">No challenge responses yet.</td></tr>'}</tbody></table></div></details>${e.target?`<p><b>Practice next:</b> ${mEsc(e.target.title)}. ${mEsc(e.target.why)}</p><button class="btn" data-growth="practice" data-mission="${s.mission}" data-practice-source="mentor">Practice from these responses ↗</button><p class="lab-small">An unfinished practice visit resumes first.</p>`:''}<div class="btn-row">${mButton('Download learner challenge CSV ↓','evidence','',true)}</div></div>`;}

function mentorOutcome(){const s=mentorState,c=mentorCoverage(s),last=s.audits.at(-1),passed=last.cards.filter(x=>x.pipCorrect).length;return`<section class="panel mentor-outcome"><div class="panel-body"><div class="eyebrow">${s.phase==='story'?'03 / YOUR TEACHER STORY':'A USEFUL SURPRISE'}</div><h2>${s.phase==='story'?'You helped an idea travel.':'Pip needs a different example.'}</h2><p>Pip used its rule correctly on <b>${passed} of 3</b> fresh challenges. This describes Pip’s rule, not your mastery.</p><div class="mentor-change"><div><span>PIP AT THE START</span><strong>${c.before}<small> / ${c.total}</small></strong></div><span aria-hidden="true">→</span><div><span>PIP AFTER YOUR EXAMPLES</span><strong>${c.now}<small> / ${c.total}</small></strong></div></div><p class="lab-small">A check of Pip’s current rule across the stated ${s.mission==='fraction'?'49 ordered unit-fraction pairs (2 to 8 parts)':'252 distinct-symbol loops (2 to 3 tiles, 2 to 8 shown)'}. It is not a learning-gain score.</p>${mentorLensPanel()}${s.phase==='coach'?`<p>Your examples fit more than one idea. Pip kept an idea that worked before but missed a new case. You can teach the missing example.</p>${mButton('Teach Pip the missing example →','coach')}`:`<h3>How do you feel about teaching this?</h3><div class="mentor-feelings" role="group" aria-label="Teaching readiness">${[['ready','I could teach it'],['unsure','Still a little unsure'],['help','With a little help'],['skip','Skip']].map(([v,label])=>mButton(label,'confidence',`data-value="${v}" aria-pressed="${s.confidence===v}"`,true)).join('')}</div><form id="mentor-words"><label for="mentor-story">What did you do that helped Pip? <small>Your words are optional.</small></label><textarea id="mentor-story" name="words" rows="3" maxlength="400" placeholder="I showed Pip a different example because…">${mEsc(s.words)}</textarea><button class="btn" type="submit">Keep my words</button><p id="mentor-words-status" role="status"></p></form><div class="btn-row">${mButton('Download my teaching story ↓','download')}${mButton('Back to my bookshelf','home','',true)}</div>`}<label class="mentor-support">Adult help with this lesson<select data-mentor-support aria-label="Help in Teach Pip">${[['unknown','Not recorded / not known'],['independent','No tutor help reported'],['tutor','Tutor helped']].map(([v,label])=>`<option value="${v}" ${s.support===v?'selected':''}>${label}</option>`).join('')}</select></label></div></section>`;}
function showMentor(m='fraction'){if(!['fraction','pattern'].includes(m))m='fraction';history.replaceState(null,'',location.pathname+location.search+'#teach-'+m);mentorError='';mentorLensIndex=0;mentorLensOpen=false;try{const raw=mRead(mKey(m));mentorState=raw?restoreMentor(raw,m):newMentor(m,mentorSeed(m,mRead('fixiverse-foundry-v1'),mRead('fixiverse-pattern-v1')));}catch{mentorState=newMentor(m);mentorError='The saved lesson could not be replayed. A new draft is open; the previous record stays until your next change.';}renderMentor();}
function renderMentor(keep=false,selector=null){const y=scrollY,s=mentorState,prefs=mRead('fixiverse-access-v1')||{};document.title='Fixiverse · Teach Pip';mentorRoot.className=`hub storybook-mission rule-lab-screen mentor-screen ${prefs.large?'large':''} ${prefs.motion?'reduced':''}`;mentorRoot.dataset.mentorPhase=s.phase;mentorRoot.dataset.mentorSubject=s.mission;mentorRoot.innerHTML=`<header><div class="brand">fixiverse <span class="growth-bookmark">PIP’S LEARNING NOTEBOOK</span></div><div class="header-actions">${mButton('My bookshelf','home','',true)}${mButton('Tutor notes','tutor','',true)}${mButton('Read aloud','read','',true)}${mButton('Aa Text size','text',`aria-pressed="${!!prefs.large}"`,true)}</div></header><main id="main" class="rule-lab-shell"><div class="mentor-masthead"><div><div class="eyebrow">TEACH PIP / YOUR IDEAS MAKE THE LESSON</div><h1 id="screen-title" tabindex="-1">${s.phase==='teach'?'Today, Pip learns<br>from you.':s.phase==='challenge'?'Can Pip use<br>your lesson?':s.phase==='coach'?'A gap is a place<br>to start again.':'Look what your<br>teaching changed.'}</h1><p>Help Pip learn from your examples. Then check whether its rule works on new problems.</p></div><div class="mentor-seal" aria-hidden="true"><span>✧</span>YOU ARE<br>THE TEACHER</div></div><nav class="lab-subjects" aria-label="Teach Pip subject">${[['fraction','Teach fractions'],['pattern','Teach patterns']].map(([m,label])=>mButton(label,'open',`data-mission="${m}" aria-pressed="${m===s.mission}"`,true)).join('')}</nav>${`<nav class="chapter-progress mentor-progress" aria-label="Teaching progress">${["Teach","Try new examples","Reflect"].map((label,i)=>`<span ${i===(s.phase==='teach'?0:s.phase==='challenge'?1:2)?'aria-current="step"':''}>${i+1} ${label}</span>`).join('')}</nav>`}${mentorError?`<p class="result soft" role="alert">${mEsc(mentorError)}</p>`:''}<div class="lab-main-grid"><div>${s.phase==='teach'?teachingPanel():s.phase==='challenge'?challengePanel():mentorOutcome()}</div>${mentorNotebook()}</div><p class="growth-local">${window.fixiverseStorage.memoryOnly?'Temporary memory: download a workspace backup before closing.':'Saved for this learner on this device.'} No timer. No grades. Help belongs here.</p></main>`;window.fixiverseMissionUI(mentorRoot,{phase:'mentor-'+s.mission+'-'+s.phase,instruction:s.phase==='teach'?(s.examples.some(e=>JSON.stringify(e.task)===JSON.stringify(s.task))?'This example is in your lesson. Change the controls to teach another, or select Test Pip on 3 new examples.':s.feedback.startsWith('Let’s check')?'Choose a different answer, or select Show me how to compare for a hint.':s.choice?'Select Teach Pip this example. Pip changes only when your answer fits the visible model.':'Look at the shaded pieces or repeating tiles. Choose your answer, then teach it to Pip.'):s.phase==='challenge'?(s.challenges[s.challengeIndex].checked?'Compare both answers with the model below. Then continue to the next example.':s.choice?'Select Open Pip’s answer and check.':'Choose your answer before revealing Pip’s answer.'):s.phase==='coach'?'Select Teach Pip the missing example. This example can help fix the gap in its rule.':'Choose how ready you feel to teach this idea. Your own words are optional.'});if(keep){scrollTo(0,y);if(selector){const target=mentorRoot.querySelector(selector)||mentorRoot.querySelector('.result');if(target){if(!target.matches('button,select,input,textarea'))target.tabIndex=-1;target.focus({preventScroll:true});}}}else{document.querySelector('#screen-title').focus({preventScroll:true});scrollTo(0,0);}}
function saveMentor(action){const next=mentorStep(mentorState,action);window.fixiverseStorage.setItem(mKey(next.mission),JSON.stringify(next));mentorState=next;}
function mentorSection(){return`<section class="tutor-section"><div class="section-heading"><h2>When the learner becomes the teacher</h2><span>Teaching examples, transfer gaps and self-reports</span></div><div class="signal-grid">${['fraction','pattern'].map(m=>{let s;try{const raw=mRead(mKey(m));if(raw)s=restoreMentor(raw,m);}catch{}const c=s?mentorCoverage(s):null;return`<article class="signal-card"><span class="mission-number">${m==='fraction'?'FRACTIONS':'PATTERNS'} / TEACH PIP</span><h3>Their own little lesson</h3><p>${s?`${s.examples.length} teaching ${s.examples.length===1?'example':'examples'} · ${s.attempts.filter(a=>!a.correct).length} examples revisited before teaching · ${s.audits.length} challenge ${s.audits.length===1?'round':'rounds'} · ${s.hints} model traces.`:'No teaching lesson recorded.'}</p>${s?`<p>${s.linked?'Started from a rule matching a prior recorded mistake.':'Started from a built-in puzzling rule.'} Pip’s finite rule check: ${c.before} → ${c.now} of ${c.total}.</p><p>Teaching readiness: ${mEsc(s.confidence?{ready:'I could teach it',unsure:'Still a little unsure',help:'With a little help',skip:'Skipped'}[s.confidence]:'Not recorded')}. ${s.support==='tutor'?'Tutor helped.':s.support==='independent'?'No tutor help reported.':'Adult help unknown.'}</p>${s.words?`<blockquote>${mEsc(s.words)}</blockquote>`:''}${mentorLearnerEvidence(s)}<p class="next-practice">${mentorEvidence(s).target?'Next: revisit the learner’s missed or unsure challenge with targeted practice.':s.phase==='coach'?'Next: coach the gap revealed by Pip’s challenge.':s.phase==='teach'?'Next: try a different example, then challenge Pip.':s.phase==='challenge'?'Next: finish the current challenge round.':'Next: ask the learner to explain the idea on a new real-world problem.'}</p>`:''}${mButton(s?'Return to Teach Pip ↗':'Open Teach Pip ↗','open',`data-mission="${m}"`)}<p class="lab-small">Pip’s performance is simulated rule behavior, not the child’s learning outcome.</p></article>`;}).join('')}</div></section>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-mentor]');if(!b)return;mentorError='';const a=b.dataset.mentor;try{if(a==='inspect'){const i=Number(b.dataset.index);if(!Number.isInteger(i)||i<0||i>=mentorState.examples.length)throw Error('Choose a teaching example.');mentorLensIndex=i;mentorLensOpen=true;renderMentor(true,`[data-mentor="inspect"][data-index="${i}"]`);return;}if(a==='evidence'){const states=['fraction','pattern'].map(m=>{try{const raw=mRead(mKey(m));return raw?restoreMentor(raw,m):null;}catch{return null;}}),alias=window.fixiverseProfiles.list().find(p=>p.id===window.fixiverseProfiles.active()).alias,result=mentorEvidenceCSV(alias,states),url=URL.createObjectURL(new Blob([result.csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='fixiverse-learner-teaching-evidence.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#announcement').textContent=`Downloaded ${result.count} learner challenge responses.`;return;}if(a==='open'){showMentor(b.dataset.mission);return;}if(a==='home'){window.fixiverseHome();return;}if(a==='tutor'){location.hash='tutor';window.fixiverseTutor.show();return;}if(a==='read'){if('speechSynthesis'in window){speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance(document.querySelector('main').innerText));}else document.querySelector('#announcement').textContent='Read-aloud is unavailable on this device.';return;}if(a==='text'){const prefs=mRead('fixiverse-access-v1')||{};prefs.large=!prefs.large;window.fixiverseStorage.setItem('fixiverse-access-v1',JSON.stringify(prefs));renderMentor(true,'[data-mentor="text"]');return;}if(a==='download'){const s=mentorState;if(s.phase!=='story')throw Error('Finish a challenge round first.');const c=mentorCoverage(s),core=lessonLens(s).minimum,alias=window.fixiverseProfiles.list().find(p=>p.id===window.fixiverseProfiles.active()).alias,lines=[`${alias}’s teaching story`,'I taught Pip with these examples:',`Smallest subset with the same rule evidence in this four-rule collection: ${core.map(i=>i+1).join(', ')}.`,...s.examples.map(e=>`${mTaskName(e.task)} → ${mentorNames[e.choice]}`),`Pip’s finite rule check: ${c.before} → ${c.now} of ${c.total}. This is Pip’s performance, not my mastery score.`,s.words||'My words: not recorded.',`Readiness: ${s.confidence||'not recorded'}. Adult help: ${s.support}. Model traces: ${s.hints}.`],u=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'})),link=document.createElement('a');link.href=u;link.download=`fixiverse-${s.mission}-teaching-story.txt`;link.click();setTimeout(()=>URL.revokeObjectURL(u),1000);document.querySelector('#announcement').textContent='Your teaching story was downloaded.';return;}saveMentor({type:a,value:b.dataset.value});renderMentor(['choose','teach','undo','confidence','check','hint'].includes(a),`[data-mentor="${a==='check'?'next':a}"]${a==='choose'||a==='confidence'?`[data-value="${b.dataset.value}"]`:''}`);document.querySelector('#announcement').textContent=mentorState.feedback|| (a==='check'?'Pip’s sealed answer and the model are now shown.':'');}catch(err){mentorError=err.message;if(mentorState)renderMentor(true);}});
document.addEventListener('change',e=>{const b=e.target;if(!b.matches('[data-mentor-field],[data-mentor-support]'))return;mentorError='';let selector='[data-mentor-support]';try{if(b.matches('[data-mentor-support]'))saveMentor({type:'support',value:b.value});else{const t=structuredClone(mentorState.task),f=b.dataset.mentorField;selector=`[data-mentor-field="${f}"]`;if(f.startsWith('part-'))t.pair[+f.at(-1)]=+b.value;else if(f==='length')t.length=+b.value;else if(f==='size'){if(+b.value===2)t.block=t.block.slice(0,2);else if(t.block.length===2)t.block.push(mentorTokens.find(v=>!t.block.includes(v)));}else t.block[+f.at(-1)]=b.value;saveMentor({type:'case',task:t});}renderMentor(true,selector);}catch(err){mentorError=err.message;renderMentor(true,selector);}});
document.addEventListener('submit',e=>{if(e.target.id!=='mentor-words')return;e.preventDefault();try{saveMentor({type:'words',value:new FormData(e.target).get('words')});document.querySelector('#mentor-words-status').textContent='Your teaching story is saved.';}catch(err){document.querySelector('#mentor-words-status').textContent=err.message;}});
document.addEventListener('toggle',e=>{if(e.target.id==='mentor-lens')mentorLensOpen=e.target.open;},true);
window.fixiverseMentor={show:showMentor,section:mentorSection,practiceTarget:m=>{try{const raw=mRead(mKey(m));return raw?mentorEvidence(restoreMentor(raw,m)).target:null;}catch{return null;}}};
